package com.example.lrb.service.impl;
import com.example.lrb.dao.GoodsDao; import com.example.lrb.dao.UserGoodsDao; import com.example.lrb.pojo.Goods; import com.example.lrb.pojo.UserGoods; import com.example.lrb.service.UserGoodsService; import com.example.lrb.vo.JsonResult; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.List;
@Service public class UserGoodsServiceImpl implements UserGoodsService { private final UserGoodsDao dao; private final GoodsDao goodsDao; public UserGoodsServiceImpl(UserGoodsDao dao,GoodsDao goodsDao){this.dao=dao;this.goodsDao=goodsDao;}
 @Transactional public JsonResult<UserGoods> insert(UserGoods ug){Goods g=goodsDao.selectByPrimaryKey(ug.getGoodsId());if(g==null)return JsonResult.notFound("商品不存在");if(g.getInventory()==null||g.getInventory()<=0)return JsonResult.badRequest("库存不足");ug.setMerchantId(g.getUserId());ug.setCreateTime(LocalDateTime.now());dao.insertSelective(ug);g.setInventory(g.getInventory()-1);goodsDao.updateByPrimaryKeySelective(g);return JsonResult.ok(ug);}
 public JsonResult<List<UserGoods>> listByPayUserId(Integer id){return JsonResult.ok(dao.selectListByPayUserId(id));} public JsonResult<List<UserGoods>> listByMerchantId(Integer id){return JsonResult.ok(dao.selectListByMerchantId(id));} }
